//! Renders the title, the run's circumstances and the guide to the corpora.

use super::record::RunHeader;

const INTRODUCTION: &str = "# Results

**Generated by `harmo results`; do not edit by hand.** It runs `bench` on `test`, `agreement`, `tune` and `agreement-tune`, and `diagnose` on `tune` and `agreement-tune`, and writes every figure they compute here. The README's Benchmarks section defines the sets and measures.

The corpora are WiR (When in Rome), ABC (Beethoven string quartets), MPS (Mozart piano sonatas), WTC (Bach's Well-Tempered Clavier), HaydnSun (Haydn's Op. 20 quartets), TAVERN (Mozart and Beethoven variations) and BPS (Beethoven piano sonata first movements). `tune` adds When in Rome categories outside AugmentedNet, such as early choral music and lieder.

Labels are compared at every thirty-second note, called a **frame**. Unless a table says otherwise, a figure is the percentage of frames on which the engine's top reading is right in that respect.
";

/// Readable names for the search settings, in the order they are listed.
const SETTING_NAMES: [(&str, &str); 10] = [
    ("beam", "beam width"),
    ("candidates", "candidate readings per slice"),
    ("distinct_depth", "distinct depth"),
    ("offer_count", "readings offered at most"),
    ("offer_margin", "offer margin"),
    ("offer_lag", "offer lag in quarter notes"),
    ("key_offer_margin", "key offer margin"),
    ("chord_offer_margin", "chord offer margin"),
    ("numeral_offer_margin", "numeral offer margin"),
    ("timing_tolerance", "RN eq timing tolerance in quarter notes"),
];

pub fn render_header(header: &RunHeader) -> String {
    let weights = header.weights.as_deref().map_or("the defaults".to_string(), |w| format!("`{w}`"));
    let changes = if header.has_uncommitted_changes { " plus uncommitted changes" } else { "" };
    let lines = [
        format!("- **Engine:** commit `{}`{changes}, with weights from {weights}", header.commit),
        format!("- **Generated:** {}", header.date),
        format!("- **Search settings:** {}", settings(header)),
        format!("- **Runtime:** {}", runtime(header)),
        format!("- **Pieces:** {} evaluated{}", header.pieces, failures(header)),
    ];
    format!("{INTRODUCTION}\n{}\n", lines.join("\n"))
}

fn settings(header: &RunHeader) -> String {
    let value = |key: &str| header.settings.get(key).map_or("?".to_string(), |v| v.to_string());
    let named = SETTING_NAMES.iter().map(|(key, name)| format!("{name} {}", value(key)));
    named.collect::<Vec<_>>().join(", ")
}

fn runtime(header: &RunHeader) -> String {
    format!(
        "{:.1} s in all on {} threads: {:.1} s for the benchmark and {:.1} s for the diagnosis",
        header.total_seconds, header.threads, header.bench_seconds, header.diagnose_seconds
    )
}

fn failures(header: &RunHeader) -> String {
    if header.failures.is_empty() {
        return String::new();
    }
    let listed: Vec<String> = header.failures.iter().map(|(id, why)| format!("`{id}` ({why})")).collect();
    format!("; left out because they could not be loaded: {}", listed.join(", "))
}
